 "content": "def transform(grid):
    # In the stripe example, the all-zero first row is replaced by the last row.
    if grid and all(v == 0 for v in grid[0]):
        out = [row[:] for row in grid]
        out[0] = out[-1][:]
        return out

    # Colored diagonal rays encode a periodic pattern by their c-r offsets.
    n = len(grid)
    anchors = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                anchors[c - r] = value

    # Find the smallest period compatible with all observed diagonal offsets.
    period = next(
        (p for p in range(1, n + 1)
         if all(anchors[a] == anchors[b]
                for a in anchors for b in anchors
                if (a - b) % p == 0)),
        n,
    )
    assigned = {offset % period: value for offset, value in anchors.items()}
    cycle = [assigned.get(i) for i in range(period)]
    observed = sorted(assigned)
    if not observed:
        return [row[:] for row in grid]
    for i in range(period):
        if cycle[i] is None:
            previous = max((k for k in observed if k < i), default=observed[-1])
            cycle[i] = assigned[previous]
    return [[cycle[(c - r) % period] for c in range(n)] for r in range(n)]
